 let width=0,height=0,dpr=1,raf=0,lastTime=0,time=0;
 let pointerX=0,pointerY=0,targetX=0,targetY=0;
 const resize=()=>{const rect=canvas.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,compact?1.2:1.5);width=rect.width;height=rect.height;canvas.width=Math.max(1,Math.round(width*dpr));canvas.height=Math.max(1,Math.round(height*dpr));ctx.setTransform(dpr,0,0,dpr,0,0)};
