const loginScreen=$('#login-screen'),pass=$('#login-password'),toggle=$('#password-toggle');toggle.onclick=()=>{const show=pass.type==='password';pass.type=show?'text':'password';toggle.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');toggle.setAttribute('aria-pressed',String(show));pass.focus()};loginVisualEffects(loginScreen);const supportDialog=$('#login-support-dialog'),supportForm=$('#login-support-form'),supportFeedback=$('#login-support-feedback'),supportPanel=$('.login-support-panel');const updateSupportGlint=e=>{if(!supportPanel)return;const r=supportPanel.getBoundingClientRect();supportPanel.style.setProperty('--panel-glint-x',`${Math.max(0,Math.min(100,(e.clientX-r.left)/Math.max(1,r.width)*100)).toFixed(1)}%`);supportPanel.style.setProperty('--panel-glint-y',`${Math.max(0,Math.min(100,(e.clientY-r.top)/Math.max(1,r.height)*100)).toFixed(1)}%`)};supportDialog.addEventListener('pointermove',updateSupportGlint,{passive:true});supportDialog.addEventListener('pointerdown',updateSupportGlint,{passive:true});$('#login-support-open').onclick=()=>{supportFeedback.hidden=true;supportFeedback.textContent='';supportForm.hidden=false;supportForm.elements.form_opened_at.value=String(Date.now());if(!supportForm.dataset.idempotencyKey)supportForm.dataset.idempotencyKey=crypto.randomUUID();supportDialog.showModal();supportForm.elements.email.focus({preventScroll:true})};$('#login-support-close').onclick=()=>supportDialog.close();supportDialog.addEventListener('click',e=>{if(e.target===supportDialog)supportDialog.close()});supportForm.onsubmit=async e=>{e.preventDefault();if(!supportForm.reportValidity())return;const button=supportForm.querySelector('[type=submit]'),data=new FormData(supportForm),payload={email:data.get('email'),company:data.get('company'),reason:data.get('reason'),details:data.get('details'),website:data.get('website'),form_opened_at:data.get('form_opened_at')},fingerprint=JSON.stringify(payload);let key=supportForm.dataset.idempotencyKey;if(!key||supportForm.dataset.idempotencyFingerprint!==fingerprint){key=crypto.randomUUID();supportForm.dataset.idempotencyKey=key;supportForm.dataset.idempotencyFingerprint=fingerprint}button.disabled=true;button.setAttribute('aria-busy','true');button.querySelector('span').textContent='Enviando solicitação...';supportFeedback.hidden=true;try{const response=await fetch(API+'/api/public/support-contact',{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','Idempotency-Key':key},body:JSON.stringify(payload)});const result=await response.json().catch(()=>({}));if(!response.ok||!result.ok)throw Error(result.error||'Não foi possível enviar agora. Tente novamente mais tarde.');supportFeedback.hidden=false;supportFeedback.className='login-support-feedback is-success';supportFeedback.textContent='Solicitação enviada para a equipe Certus. Ela responderá pelo e-mail informado.';supportForm.hidden=true;delete supportForm.dataset.idempotencyKey;delete supportForm.dataset.idempotencyFingerprint}catch(error){supportFeedback.hidden=false;supportFeedback.className='login-support-feedback is-error';supportFeedback.textContent=error.message;button.disabled=false;button.removeAttribute('aria-busy');button.querySelector('span').textContent='Enviar solicitação'}};supportDialog.addEventListener('close',()=>{supportForm.reset();supportForm.hidden=false;delete supportForm.dataset.idempotencyKey;delete supportForm.dataset.idempotencyFingerprint;const submit=supportForm.querySelector('[type=submit]');if(submit){submit.disabled=false;submit.removeAttribute('aria-busy');submit.querySelector('span').textContent='Enviar solicitação'}supportFeedback.hidden=true;supportFeedback.textContent=''});
