function traduzirTexto(valor){const t=String(valor??'');const mapa={"Authentication required":"Entre na sua conta para continuar.","Invalid or expired session":"Sua sessão expirou. Entre novamente.","Session is no longer active":"Sua sessão foi encerrada. Entre novamente.","Unable to validate session":"Não foi possível validar sua sessão.","Email and password are required":"Informe seu e-mail e sua senha.","Email, password and company slug are required":"Informe e-mail, senha e identificador da empresa.","Invalid credentials or inactive account":"E-mail, senha ou empresa não conferem, ou a conta está inativa.","Unable to authenticate":"Não foi possível entrar.","Unable to load employees":"Não foi possível carregar os colaboradores.","Active employee profile not found":"Cadastro ativo de colaborador não encontrado.","Employee not found":"Colaborador não encontrado.","Unable to load branches":"Não foi possível carregar as filiais.","Unable to load accounts":"Não foi possível carregar as contas de acesso.","Unable to create account":"Não foi possível criar o acesso.","Unable to update employee":"Não foi possível atualizar o cadastro do colaborador.","Unable to load clock events":"Não foi possível carregar as marcações.","Unable to load requests":"Não foi possível carregar as solicitações.","No employee profile is assigned":"Este acesso não está vinculado a um cadastro de colaborador.","No access":"Você não tem acesso a este conteúdo.","Invalid date filter":"O filtro de datas é inválido.","Employee number already exists":"Esta matrícula já está cadastrada.","Valid full_name is required":"Informe um nome válido.","A valid action and explanatory note are required":"Informe uma decisão válida e explique o motivo.","Unable to review adjustment":"Não foi possível analisar a solicitação.","Unable to create employee":"Não foi possível cadastrar o colaborador.","Unable to update account":"Não foi possível atualizar o acesso.","Unable to load departments":"Não foi possível carregar os departamentos.","Unable to load schedules":"Não foi possível carregar as jornadas.","Invalid request":"A solicitação contém dados inválidos.","API route not found":"Esta função não está disponível.","Employee account required":"Acesse pelo perfil de colaborador.","Employee portal access required":"Acesse o portal do colaborador.","Unable to load attachment":"Não foi possível abrir o anexo.","Attachment not found":"O anexo não foi encontrado."};return mapa[t]||t}
function initialPasswordGate(){root.innerHTML=`<main class="login"><form class="card login-card" id="initial-password-form"><img class="brand-logo" src="./certus-logo-color.png" alt="Certus by VagasIO"><p class="eyebrow">Primeiro acesso</p><h1>Crie sua senha pessoal</h1><p>Por segurança, altere a senha temporária antes de continuar.</p><div id="initial-password-message" class="message" role="alert" hidden></div><label>Nova senha<input name="new_password" type="password" autocomplete="new-password" minlength=14 required></label><label>Confirme a nova senha<input name="confirm_password" type="password" autocomplete="new-password" minlength=14 required></label><button class="primary">Salvar nova senha</button></form></main>`;$('#initial-password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),a=String(f.get('new_password')),b=String(f.get('confirm_password')),m=$('#initial-password-message'),btn=e.currentTarget.querySelector('button');if(a!==b){m.hidden=false;m.className='message bad';m.textContent='As senhas não coincidem.';return}if(a.length<14){m.hidden=false;m.className='message bad';m.textContent='Use pelo menos 14 caracteres.';return}btn.disabled=true;btn.textContent='Salvando…';try{await api('/api/account/initial-password',{method:'POST',body:JSON.stringify({new_password:a})});token='';user=null;sessionStorage.removeItem(tokenKey);sessionStorage.removeItem(userKey);clearPersistentSession();login('Senha alterada. Entre novamente com a nova senha.')}catch(err){m.hidden=false;m.className='message bad';m.textContent=err.message;btn.disabled=false;btn.textContent='Salvar nova senha'}}}
