function recentClocksHtml(items){const names={entry:'Entrada',break_start:'Saída para intervalo',break_end:'Retorno do intervalo',exit:'Saída'},rows=(items||[]).slice(0,5);return rows.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Marcações recentes"><table><thead><tr><th>Funcionário</th><th>Tipo</th><th>Data e hora</th><th>Estado</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${esc(names[x.event_type]||x.event_type)}</td><td>${esc(formatDateTime(x.occurred_at))}</td><td>${esc(statusLabel(x.validation_status))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><strong>Nenhuma marcação registrada</strong><p>Quando um funcionário marcar o ponto, o registro aparecerá aqui.</p></div>'}
let workerRecordsExpanded=false;let faceApiReady=null;let offlinePreparePromise=null;let dashboardRefreshTimer=null;async function loadFaceApi(){if(faceApiReady)return faceApiReady;faceApiReady=new Promise((resolve,reject)=>{if(window.faceapi)return resolve(window.faceapi);const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/dist/face-api.js';script.crossOrigin='anonymous';script.onload=()=>resolve(window.faceapi);script.onerror=()=>reject(Error('Não foi possível carregar o reconhecimento facial')) ;document.head.append(script)}).then(async f=>{const base='https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/model';await Promise.all([f.nets.ssdMobilenetv1.loadFromUri(base),f.nets.faceLandmark68Net.loadFromUri(base),f.nets.faceRecognitionNet.loadFromUri(base)]);return f});faceApiReady.catch(()=>{faceApiReady=null});return faceApiReady}
async function faceDescriptor(video){const f=await loadFaceApi();const r=await f.detectSingleFace(video,new f.SsdMobilenetv1Options({minConfidence:0.65})).withFaceLandmarks().withFaceDescriptor();if(!r)throw Error('__FACE_NOT_FOUND__');return Array.from(r.descriptor)}
async function withCamera(run){if(!navigator.mediaDevices?.getUserMedia)throw Error('Este aparelho/navegador não liberou acesso à câmera');const video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;const dialog=document.createElement('dialog');dialog.className='dialog face-dialog';dialog.innerHTML='<form class="card dialog-card face-dialog-card" method="dialog"><button class="face-close" value="cancel" aria-label="Cancelar reconhecimento">×</button><span class="face-eyebrow">CERTUS · MEU PONTO</span><h2>Reconhecimento facial</h2><p class="face-description">Centralize o rosto no círculo. A câmera analisa a imagem e confirma com o cadastro automaticamente. Foto e vídeo não são enviados nem armazenados.</p><div class="face-camera-ring"><div id="face-camera"></div><span class="face-guide" aria-hidden="true"></span></div><div class="face-progress" role="status" aria-live="polite"><span class="face-pulse"></span><span id="face-progress-text">Iniciando câmera…</span></div><button class="secondary face-cancel" value="cancel">Cancelar</button></form>';dialog.querySelector('#face-camera').append(video);document.body.append(dialog);const progress=dialog.querySelector('#face-progress-text');let stream,closed=false;try{dialog.showModal();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:640},aspectRatio:{ideal:1}},audio:false});video.srcObject=stream;await new Promise((resolve,reject)=>{video.onloadedmetadata=resolve;video.onerror=()=>reject(Error('Câmera indisponível'))});await video.play().catch(()=>{});return await new Promise((resolve,reject)=>{dialog.addEventListener('cancel',()=>{closed=true;reject(Error('Reconhecimento cancelado'))},{once:true});dialog.addEventListener('close',()=>{if(!closed)reject(Error('Reconhecimento cancelado'))},{once:true});const loop=async()=>{if(closed||!dialog.open)return;try{const result=await run(video,text=>{if(progress)progress.textContent=text});closed=true;resolve(result)}catch(e){if(closed||!dialog.open)return;if(e?.message==='__FACE_NOT_FOUND__'||e?.message==='__FACE_LOW_QUALITY__'){if(progress)progress.textContent=e.message==='__FACE_LOW_QUALITY__'?'Ajuste a distância e a iluminação; mantenha o rosto dentro do círculo…':'Posicione o rosto dentro do círculo…';setTimeout(loop,500);return}if(e?.message==='__FACE_MISMATCH__'){if(progress)progress.textContent='Rosto não confirmado. Ajuste a posição e tente novamente…';setTimeout(loop,650);return}closed=true;reject(e)}};loop()})}finally{stream?.getTracks().forEach(t=>t.stop());if(dialog.open)dialog.close();dialog.remove()}}
async function prepareOfflineClock(){if(offlinePreparePromise)return offlinePreparePromise;if(!navigator.onLine||user?.role!=='employee'||!user?.employee_id)return false;offlinePreparePromise=(async()=>{if('serviceWorker'in navigator){try{await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(resolve=>{const timer=setTimeout(resolve,5000);navigator.serviceWorker.addEventListener('controllerchange',()=>{clearTimeout(timer);resolve()},{once:true})})}catch{}if(!navigator.serviceWorker.controller)return false}const [workplace]=await Promise.all([api('/api/employee/work-location'),loadFaceApi()]);if(!workplace||workplace.latitude==null||workplace.longitude==null||!workplace.branch_id)throw Error('Filial ou coordenadas indisponíveis');sessionStorage.setItem('certus_workplace',JSON.stringify({employee_id:user.employee_id,company_id:user.company.id,...workplace}));const db=await offlineDb();await offlineKey(db);db.close();try{if(navigator.storage?.persist)await navigator.storage.persist()}catch{}return true})().catch(()=>false).finally(()=>{offlinePreparePromise=null});return offlinePreparePromise}async function faceStatus(){const key=`certus_face_profile:${user?.company?.id||''}:${user?.employee_id||''}`;let cached=null;try{cached=JSON.parse(sessionStorage.getItem(key)||'null')}catch{}if(!navigator.onLine){if(cached&&typeof cached.registered==='boolean')return{registered:cached.registered,consented_at:cached.consented_at||null,offline_cached:true};throw Error('Sem conexão e sem situação facial previamente verificada neste aparelho.')}try{const profile=await api('/api/employee/face-profile');sessionStorage.setItem(key,JSON.stringify({registered:!!profile.registered,consented_at:profile.consented_at||null,saved_at:Date.now()}));if(profile.registered)prepareOfflineClock().catch(()=>{});return profile}catch(e){if((e?.name==='TypeError'||e?.name==='AbortError')&&cached&&typeof cached.registered==='boolean')return{registered:cached.registered,consented_at:cached.consented_at||null,offline_cached:true};throw e}}
async function captureFaceProfile(video,state){const f=await loadFaceApi(),samples=[];let previous=null;while(samples.length<5){const r=await f.detectSingleFace(video,new f.SsdMobilenetv1Options({minConfidence:0.65})).withFaceLandmarks().withFaceDescriptor();if(!r)throw Error('__FACE_NOT_FOUND__');const box=r.detection.box,frameWidth=video.videoWidth||640;if(r.detection.score<0.75||box.width/frameWidth<0.18)throw Error('__FACE_LOW_QUALITY__');const d=Array.from(r.descriptor);if(previous){const delta=Math.sqrt(previous.reduce((sum,v,i)=>sum+(v-d[i])**2,0));if(delta>=0.32){samples.length=0;previous=d;state('Mantenha o rosto parado e bem iluminado; estabilizando a captura…');throw Error('__FACE_NOT_FOUND__')}}previous=d;samples.push(d);state(`Captura nítida ${samples.length} de 5…`);if(samples.length<5)await new Promise(resolve=>setTimeout(resolve,180))}return samples[0].map((_,i)=>samples.reduce((sum,d)=>sum+d[i],0)/samples.length)}
async function enrollFace(){try{if(!confirm('Consentimento separado: autoriza armazenar seu modelo facial para conferir suas marcações? O reconhecimento não prova presença real.'))return;const descriptor=await withCamera(async(video,state)=>captureFaceProfile(video,state));await api('/api/employee/face-profile',{method:'POST',body:JSON.stringify({consent:true,descriptor})});message('Cadastro facial realizado com cinco capturas nítidas e consistentes. Para refazer, solicite liberação do gestor no terminal compartilhado.')}catch(e){message(e.message,true)}await load('worker')}
function timesheetMinutes(value){if(!Number.isFinite(value))return 'Não informado';const sign=value<0?'−':'';const n=Math.abs(Math.round(value));return `${sign}${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function timesheetCount(report){return (report?.days||[]).reduce((n,d)=>n+(d.marks?.length||0),0)}
function reportDuration(value){return Number.isInteger(value)?`${String(Math.floor(Math.abs(value)/60)).padStart(2,'0')}h${String(Math.abs(value)%60).padStart(2,'0')}min`:'—'}
function reportDurationSeconds(value){if(!Number.isInteger(value))return '—';const n=Math.abs(value),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return `${String(h).padStart(2,'0')}h${String(m).padStart(2,'0')}min${s?` ${String(s).padStart(2,'0')}s`:''}`} 
function reportSigned(value){return Number.isInteger(value)?`${value>0?'+':value<0?'-':''}${reportDuration(Math.abs(value))}`:'—'}
function reportSchedule(d){if(d.schedule?.restDay)return 'DSR';if(d.schedule?.pairs?.length)return d.schedule.pairs.map(p=>`${p.start||p.entry}–${p.end||p.exit}`).join(' / ');if(d.schedule?.start&&d.schedule?.end)return `${d.schedule.start}–${d.schedule.end}`;if(Number.isInteger(d.plannedMinutes))return `${reportDuration(d.plannedMinutes)} prevista`;return d.scheduleSource==='missing'?'Jornada não informada':'Programação não informada'}
function reportContract(schedule){const r=schedule?.rules;if(!r)return schedule?.name||'Jornada não informada';const source=r.daily_schedule||r.weekdays||r.weekday?.daily_schedule||r.weekday||r.days||r;if(Array.isArray(source))return `${schedule.name||'Escala cadastrada'} | horários conforme escala`;if(source.start||source.entry){const weekly=source.weekly_hours??source.weeklyHours??r.weekly_hours??r.weeklyHours;const a=source.break_start||source.breakStart,b=source.break_end||source.breakEnd;const br=a&&b?`${a} às ${b}`:Number(source.break_minutes??source.breakMinutes)>0?`${reportDuration(Number(source.break_minutes??source.breakMinutes))} de intervalo`:'conforme escala';return `${schedule.name||'Jornada cadastrada'} | Entrada: ${source.start||source.entry} | Intervalo: ${br} | Saída: ${source.end||source.exit||'—'} | Carga horária: ${Number.isFinite(Number(weekly))?`${weekly}h semanais`:'conforme cadastro'}`}const days=Object.entries(source).filter(([,d])=>d&&typeof d==='object'),rests=days.filter(([,d])=>d.rest===true||d.is_rest===true).map(([k])=>k);return `${schedule.name||'Escala cadastrada'} | Horários variáveis conforme escala${rests.length?` | DSR: ${rests.join(', ')}`:''}`}
function reportObservations(d){const out=[],hasManual=(d.rawMarkEvents||[]).some(m=>m.manualAddition||m.adjusted||m.metadata?.manual_addition===true||m.metadata?.correction_of),retifications=[...String(d.justification||'').matchAll(/Retificação aprovada: batida das (\d{1,2}:\d{2}) removida do cálculo/g)].map(m=>m[1]);if(d.status==='absent')out.push('Falta');if(d.abonoType==='day'||d.status==='aboned')out.push('Abono dia');else if(d.abonoType==='hours')out.push('Abono horas');if(hasManual)out.push('Ajuste manual');if(retifications.length)out.push(`Retif. ${[...new Set(retifications)].join(', ')}`);if(d.schedule?.restDay)out.push('DSR');if(Number(d.extra50Minutes)>0)out.push('Extra 50%');if(Number(d.extra100Minutes)>0)out.push('Extra 100%');const warningMap={schedule_missing_overtime_unclassified:'Jornada ausente',schedule_invalid_overtime_unclassified:'Revisar jornada',unsupported_stored_schedule_snapshot:'Revisar jornada',invalid_schedule_snapshot:'Revisar jornada',conflicting_schedule_snapshots:'Revisar jornada',invalid_or_unsupported_schedule:'Revisar jornada',clock_schedule_missing_tardiness_unclassified:'Jornada parcial',overtime_unclassified_due_to_mark_occurrences:'',holiday_work_100_percent_not_bankable:'Feriado 100%',sunday_dsr_premium_not_bankable:'DSR 100%',monthly_bank_candidate_cap_reached:'Limite banco',global_bank_rule_disabled:'Banco não aplicado'};for(const w of d.warnings||[]){const label=warningMap[w];if(label)out.push(label)}const text=[...new Set(out)].join(' · ');return text.length>48?text.slice(0,45).trimEnd()+'…':text||'—'}
function timesheetSummary(s={}){const vals=[['Total trabalhado',reportDuration(s.workedMinutes),'workedPartial'],['Horas abonadas',reportDuration(s.approvedAbonoMinutes),null],['Horas computadas',reportDuration(s.creditedMinutes),'creditedPartial'],['Jornada prevista',reportDuration(s.scheduledMinutes),null],['Horas extras 50%',reportDuration(s.extra50Minutes),'extra50Partial'],['Horas extras 100%',reportDuration(s.extra100Minutes),'extra100Partial'],['Horas noturnas (equivalentes)',Number.isFinite(s.nightEquivalentHours)?`${s.nightEquivalentHours.toLocaleString('pt-BR',{maximumFractionDigits:2})} h`:'—',null],['Crédito por redução noturna',reportDurationSeconds(s.nightReducedCreditSeconds),null],['Adicional noturno aplicado',Number.isFinite(s.nightPremiumPercent)?`${s.nightPremiumPercent}%`:'—',null],['Prorrogação noturna',reportDuration(s.nightExtensionMinutes),null],['Saldo período',reportSigned(s.periodBalanceMinutes),'periodBalancePartial'],['Saldo do banco de horas',reportSigned(s.bankBalanceMinutes),'bankBalancePartial'],['Total de atrasos',reportDuration(s.tardinessMinutes),null],['Saldo do período',reportSigned(s.periodBalanceMinutes),'periodBalancePartial']];return `<div class="timesheet-period-total">${vals.map(([k,v,flag])=>`<div><small>${k}</small><b>${v}</b>${flag&&s[flag]?'<small class="muted">Parcial · há dia(s) não concluído(s)</small>':''}</div>`).join('')}</div>`}
function isOfflineMark(m){return m?.metadata?.capture==='shared_terminal_offline'||m?.metadata?.original_capture==='shared_terminal_offline'||m?.metadata?.capture==='authenticated_employee_offline'||m?.metadata?.offline_time_unverified===true}
function timesheetMarkSymbol(m){return isOfflineMark(m)?'<sup class=\"timesheet-mark-symbol\">#</sup>':(m?.manualAddition||m?.adjusted||m?.metadata?.manual_addition===true||m?.metadata?.correction_of)?'<sup class=\"timesheet-mark-symbol\">*</sup>':''}
function timesheetRows(report){const days=report?.days||[];if(!days.length)return '<div class="empty-state">Nenhum dado disponível neste período.</div>';const zone=report.timeZone||'America/Sao_Paulo',localToday=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),fmtTime=new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:zone}),weekday=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];return `<div class="timesheet-document-table"><table><thead><tr><th>Data</th><th>Dia da semana</th><th>Jornada</th><th>Marcações</th><th>Total trabalhado</th><th>Trabalho noturno</th><th>Saldo diário</th><th>Observações / Justificativa</th></tr></thead><tbody>${days.map(d=>{const dt=new Date(`${d.date}T12:00:00Z`),dateLabel=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'}).format(dt),marks=(report.rawMarks||[]).filter(m=>!m.retified&&!m.manualDeleted&&new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(m.timestamp))===d.date),markText=marks.map(m=>`${fmtTime.format(new Date(m.timestamp))}${timesheetMarkSymbol(m)}`).join(' | '),note=d.date>=localToday?'—':reportObservations(d);return `<tr><td>${dateLabel}</td><td>${weekday[dt.getUTCDay()]}</td><td>${esc(reportSchedule(d))}</td><td>${markText||'—'}</td><td>${esc(reportDuration(d.workedMinutes))}</td><td>${d.nightWork?`${esc(reportDuration(d.nightWork.actualNightMinutes))} real · ${esc(d.nightWork.premiumPercent)}% · ficta + ${esc(reportDurationSeconds(d.nightWork.reducedHourCreditSeconds))}${d.nightWork.extensionPremiumApplies?` + ${esc(reportDuration(d.nightWork.extensionAfterNightMinutes))} prorrogação`:''}`:'—'}</td><td>${esc(Number.isInteger(d.dailyBalanceMinutes)?reportSigned(d.dailyBalanceMinutes):'—')}</td><td>${esc(note)}</td></tr>`}).join('')}</tbody></table></div><small class="timesheet-mark-legend"># Marcação offline; * marcação manual ou ajuste aprovado. Marcas reconhecidas no terminal bloqueado são confirmadas automaticamente.</small>`}
function timesheetDocument(report){const periodSummary=report.summary||{},zone=report.timeZone||'America/Sao_Paulo',days=report.days||[],start=days[0]?.date||`${report.year}-${String(report.month).padStart(2,'0')}-01`,end=days.at(-1)?.date||start,fmt=d=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'}).format(new Date(`${d}T12:00:00Z`)),today=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),obs=days.flatMap(d=>{if(d.date>=today)return [];const text=reportObservations(d);return text==='—'?[]:[`${fmt(d.date)} — ${text}.`]});return `<article class="timesheet-document"><header class="timesheet-doc-head"><img src="./certus-logo-color.png" alt="Certus"><h2>Espelho de Ponto</h2><div><small>PERÍODO DE APURAÇÃO</small><b>${fmt(start)} a ${fmt(end)}</b></div></header><div class="timesheet-identity"><section><h3>Dados do empregador</h3><p><b>Empresa:</b> ${esc(report.companyName||report.companyRegisteredName||'Não informado')}<br><b>CNPJ:</b> ${esc(report.employerId||'Não informado')}<br><b>Filial:</b> ${esc(report.branchName||'Não informada')}<br><b>Endereço da filial:</b> ${esc(report.branchAddress||'Não informado')}</p></section><section><h3>Dados do colaborador</h3><p><b>Nome:</b> ${esc(report.employeeName||'Não informado')}<br><b>CPF:</b> ${esc(report.employeeCpf||'Não informado')}<br><b>Admissão:</b> ${esc(report.employeeAdmissionDate?fmt(String(report.employeeAdmissionDate).slice(0,10)):'Não informada')}<br><b>Cargo:</b> ${esc(report.employeeJobTitle||'Não informado')} · <b>Matrícula:</b> ${esc(report.employeeNumber||'Não informada')}</p></section></div><section class="timesheet-contract"><h3>Jornada contratual</h3><p>${esc(reportContract(report.contractualSchedule))}</p></section>${timesheetRows(report)}<h3 class="timesheet-subhead">Total do Período</h3>${timesheetSummary(periodSummary)}<h3 class="timesheet-subhead">Justificativas e Observações</h3><div class="timesheet-observations">${obs.length?obs.map(x=>`<p>${esc(x)}</p>`).join(''):'Sem justificativas ou observações no período.'}</div><footer class="timesheet-doc-sign"><span>Data e hora da emissão: ${new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}).format(new Date())} (Brasília)</span><div><section><i></i>Assinatura do colaborador</section><section><i></i>Assinatura do responsável pela empresa</section></div></footer></article>`}
async function downloadTimesheetPdf(month,year,button){const msg=$('#timesheet-message');button.disabled=true;button.textContent='Preparando PDF…';try{const response=await fetch(`${API}/api/employee/timesheet.pdf?year=${encodeURIComponent(year)}&month=${encodeURIComponent(month)}`,{headers:{Authorization:`Bearer ${token}`,Accept:'application/pdf'}});if(!response.ok){const d=await response.json().catch(()=>({}));throw Error(d.error||`Falha ${response.status}`)}const blob=await response.blob();if(blob.type!=='application/pdf')throw Error('A API não retornou um PDF válido.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`espelho-de-ponto-${year}-${String(month).padStart(2,'0')}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);if(msg){msg.hidden=false;msg.className='message';msg.textContent='PDF baixado.'}}catch(e){if(msg){msg.hidden=false;msg.className='message bad';msg.textContent=e.message}}finally{button.disabled=false;button.textContent='Baixar PDF'}}
